#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m12-node-agent-and-identity pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m12-node-agent-and-identity
CHECKS="agent-ready agent-toleration db-headless db-ready db-partition db-one-updated db-pod-names db-ordinal-versions"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m12-node-agent-and-identity
checks:
  - id: agent-ready
    describe: The node agent has a ready Pod on each of the 3 workers, the tainted one included
    kubectl:
      - get
      - daemonset
      - shelf-node-agent
      - -n
      - shelf
      - -o
      - jsonpath={.status.numberReady}/{.status.desiredNumberScheduled}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: 3/3
    hint: Compare `kubectl get daemonset shelf-node-agent --namespace shelf` with `kubectl get nodes`. A DaemonSet counts the nodes it may use, so DESIRED is lower when a taint keeps it away. Tolerate the taint of the database worker in the Pod template and apply the file.
  - id: agent-toleration
    describe: The agent tolerates the taint dedicated=db:NoSchedule
    kubectl:
      - get
      - daemonset
      - shelf-node-agent
      - -n
      - shelf
      - -o
      - jsonpath={.spec.template.spec.tolerations[?(@.key=="dedicated")].effect}
    expect:
      equals: NoSchedule
    hint: "Under `spec.template.spec` add a `tolerations` list with the key `dedicated`, the value `db` and the effect `NoSchedule`. `kubectl describe node reconcile-worker3` shows the taint. Do not tolerate everything: the control plane must stay free of the agent."
  - id: db-headless
    describe: The Service shelf-db is headless
    kubectl:
      - get
      - service
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.spec.clusterIP}
    expect:
      equals: None
    hint: "Add `clusterIP: None` to the Service's `spec`. A Service's `clusterIP` can't be changed once it is set, so if you applied the first draft, delete the Service with `kubectl delete service shelf-db --namespace shelf` and apply the file again."
  - id: db-ready
    describe: The StatefulSet shelf-db has 3 ready replicas
    kubectl:
      - get
      - statefulset
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.status.readyReplicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "3"
    hint: "Set `replicas: 3` in the StatefulSet and apply the file. The Pods start one at a time, each after the one before is Ready, so wait for `kubectl rollout status statefulset/shelf-db --namespace shelf`."
  - id: db-partition
    describe: The update is partitioned at ordinal 2
    kubectl:
      - get
      - statefulset
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.spec.updateStrategy.rollingUpdate.partition}
    expect:
      equals: "2"
    hint: "Under `spec` add `updateStrategy` with `type: RollingUpdate` and `rollingUpdate.partition: 2`. Only the ordinals 2 and up get a new template."
  - id: db-one-updated
    describe: One replica has been updated to the new revision
    kubectl:
      - get
      - statefulset
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.status.updatedReplicas}/{.status.replicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: 1/3
    hint: "The partition holds back everything below ordinal 2, so one of three replicas is updated. If all three are at the new revision, the template changed before the replicas existed: bring the replicas up at version 1 first, then change the version label and set the partition."
  - id: db-pod-names
    describe: The Pods are named shelf-db-0, shelf-db-1 and shelf-db-2
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-db
      - -o
      - jsonpath={.items[*].metadata.name}
    expect:
      equals: shelf-db-0 shelf-db-1 shelf-db-2
    hint: A StatefulSet names its Pods after itself and an ordinal, from 0 to replicas minus one. Check that `replicas` is 3 and that the Pods exist.
  - id: db-ordinal-versions
    describe: Only shelf-db-2 runs version 2, and shelf-db-0 and shelf-db-1 still run version 1
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-db
      - -o
      - jsonpath={.items[*].metadata.labels.app\.kubernetes\.io/version}
    expect:
      equals: 1 1 2
    hint: Change the label `app.kubernetes.io/version` in the Pod template from "1" to "2" and apply the file. With the partition at 2, only shelf-db-2 is replaced. Read the revision of each Pod with `kubectl get pods --namespace shelf --label-columns controller-revision-hash`.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
